#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_CHAR 20
#define MAX_TIME 30
#define MAX_NAME 11

int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        char names[MAX_CHAR][MAX_NAME];
        int times[MAX_CHAR][MAX_TIME];
        int m[MAX_CHAR];
        int time_count[MAX_TIME] = {0};
        int char_at_time[MAX_TIME][MAX_CHAR] = {{0}};
        int char_count_at_time[MAX_TIME] = {0};

        // Read input
        for (int i = 0; i < n; i++) {
            scanf("%s %d", names[i], &m[i]);
            for (int j = 0; j < m[i]; j++) {
                scanf("%d", &times[i][j]);
                int t = times[i][j];
                time_count[t]++;
                char_at_time[t][char_count_at_time[t]] = i;
                char_count_at_time[t]++;
            }
        }

        int points[MAX_CHAR] = {0};

        // Calculate points for each character
        for (int t = 0; t < MAX_TIME; t++) {
            if (char_count_at_time[t] > 0) {
                int num_chars = char_count_at_time[t];
                int pts_per_char = n - (num_chars - 1);
                for (int k = 0; k < num_chars; k++) {
                    int ci = char_at_time[t][k];
                    points[ci] += pts_per_char;
                }
            }
        }

        // Find minimum points and lexicographically smallest name
        int min_idx = 0;
        for (int i = 1; i < n; i++) {
            if (points[i] < points[min_idx] ||
                (points[i] == points[min_idx] && strcmp(names[i], names[min_idx]) < 0)) {
                min_idx = i;
            }
        }

        printf("%s %d\n", names[min_idx], points[min_idx]);
    }
    return 0;
}

