        int times[20][30];

        for (int i = 0; i < n; i++) {
            scanf("%s %d", names[i], &m[i]);
            for (int j = 0; j < m[i]; j++) {
                scanf("%d", &times[i][j]);
            }
        }

        // Count how many characters are on screen at each time
        int count[30] = {0};
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m[i]; j++) {
                count[times[i][j]]++;
            }
        }

        // Calculate points for each character
        int points[20] = {0};
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m[i]; j++) {
                int t = times[i][j];
                int k = count[t];
                points[i] += (n - k + 1);
            }
        }

        // Find minimum points
        int min_points = points[0];
        for (int i = 1; i < n; i++) {
            if (points[i] < min_points) min_points = points[i];
        }

        // Find lexicographically smallest name with min points
        char best_name[11] = "";
        for (int i = 0; i < n; i++) {
            if (points[i] == min_points) {
                if (best_name[0] == '\0' || strcmp(names[i], best_name) < 0) {
                    strcpy(best_name, names[i]);
                }
            }
        }

        printf("%s %d\n", best_name, min_points);
    }
    return 0;
}

#include <stdio.h>
