#define MAXN 25
#define MAXNAME 16

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        char names[MAXN][MAXNAME];
        int present[MAXN][30];
        int score[MAXN];
        memset(present, 0, sizeof(present));
        memset(score, 0, sizeof(score));

        for (int i = 0; i < n; i++) {
            int m;
            scanf("%s %d", names[i], &m);
            for (int j = 0; j < m; j++) {
                int d;
                scanf("%d", &d);
                present[i][d] = 1;
            }
        }

        for (int t = 0; t < 30; t++) {
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if (present[i][t]) cnt++;
            }
            if (cnt == 0) continue;

            int add = n - cnt + 1;
            for (int i = 0; i < n; i++) {
                if (present[i][t]) score[i] += add;
            }
        }

        int ans = 0;
        for (int i = 1; i < n; i++) {
            if (score[i] < score[ans] ||
                (score[i] == score[ans] && strcmp(names[i], names[ans]) < 0)) {
                ans = i;
            }
        }

        printf("%s %d\n", names[ans], score[ans]);
    }
    return 0;
}

