        int n;
        if (!(cin >> n)) return 0;
        if (n == 0) break;

        vector<string> names(n);
        vector<int> score(n, 0);
        vector<vector<int>> appear(30);

        for (int i = 0; i < n; ++i) {
            int m;
            cin >> names[i] >> m;
            for (int j = 0; j < m; ++j) {
                int d;
                cin >> d;
                appear[d].push_back(i);
            }
        }

        for (int t = 0; t < 30; ++t) {
            int k = (int)appear[t].size();
            if (k == 0) continue;
            int pts = n - k + 1;
            for (int idx : appear[t]) score[idx] += pts;
        }

        int best = 0;
        for (int i = 1; i < n; ++i) {
            if (score[i] < score[best] || (score[i] == score[best] && names[i] < names[best])) {
                best = i;
            }
        }

        cout << names[best] << ' ' << score[best] << '\n';
    }

    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            int n = sc.nextInt();
            if (n == 0) break;

            String[] names = new String[n];
            int[][] times = new int[n][];

            for (int i = 0; i < n; i++) {
                names[i] = sc.next();
                int m = sc.nextInt();
                times[i] = new int[m];
                for (int j = 0; j < m; j++) {
                    times[i][j] = sc.nextInt();
                }
            }

            // Count occurrences at each time point
            Map<Integer, Set<Integer>> timeToCharacters = new HashMap<>();
            for (int i = 0; i < n; i++) {
                for (int t : times[i]) {
                    timeToCharacters.putIfAbsent(t, new HashSet<>());
                    timeToCharacters.get(t).add(i);
                }
            }

            // Calculate points for each character
            long[] points = new long[n];
            for (Map.Entry<Integer, Set<Integer>> entry : timeToCharacters.entrySet()) {
                int k = entry.getValue().size();
                for (int idx : entry.getValue()) {
                    points[idx] += (n - k + 1);
                }
            }

            // Find minimum points and lexicographically smallest name
            long minPoints = Long.MAX_VALUE;
            String minName = "";

            for (int i = 0; i < n; i++) {
                if (points[i] < minPoints || (points[i] == minPoints && names[i].compareTo(minName) < 0)) {
                    minPoints = points[i];
                    minName = names[i];
                }
            }

            System.out.println(minName + " " + minPoints);
        }
        sc.close();
    }
}

